#!/usr/bin/env bash
# Mutation proof for honey-review-desk-install (generated by agents-bots-honey.org): each sabotaged copy MUST fail test_honey_review_desk_install.py
# by a NAMED failure. Exit 0 = every mutant killed, 1 = a survivor or an error.
set -uo pipefail
HERE="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd -P)"
PROG="${HONEY_REVIEW_DESK_INSTALL:-}"
[ -n "$PROG" ] || for c in "$HERE/../openrc/honey-review-desk-install" "$HERE/honey-review-desk-install"; do [ -f "$c" ] && { PROG="$c"; break; }; done
[ -f "$PROG" ] || { echo "mutation-check-review-desk-install: installer not found"; exit 1; }
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
fail=0; killed=0
mutate() { # name sed-expression
  local name="$1" expr="$2" d="$TMP/$1" out rc names
  mkdir -p "$d"; cp "$PROG" "$d/honey-review-desk-install"; sed -i "$expr" "$d/honey-review-desk-install"
  if cmp -s "$PROG" "$d/honey-review-desk-install"; then echo "MUTATION NOT APPLIED: $name"; fail=1; return; fi
  out="$(HONEY_REVIEW_DESK_INSTALL="$d/honey-review-desk-install" timeout 300 python3 "$HERE/test_honey_review_desk_install.py" 2>&1)"; rc=$?
  if [ "$rc" = 124 ] || ! printf '%s\n' "$out" | grep -qE '^(FAILED \(|OK)'; then echo "INFRASTRUCTURE ERROR (not a kill): $name"; printf '%s\n' "$out" | tail -4 | sed 's/^/    | /'; fail=1; return; fi
  names="$(printf '%s\n' "$out" | grep -E '^(FAIL|ERROR):' | sed 's/^[A-Z]*: //; s/ (.*//' | head -3 | tr '\n' ' ')"
  if [ -n "$names" ]; then killed=$((killed+1)); echo "killed: $name by: $names"; else echo "SURVIVED (tests too weak): $name"; fail=1; fi
}
mutate no-backup                 "s|^\[ -e \"\$DST\" \] \&\& cp -p -- \"\$DST\" \"\$DST.bak-\$ts\"|true|"
mutate mode-not-755              "s/-m 0755/-m 0777/g"
mutate drift-reports-unchanged   "s/^else state=drift; fi/else state=unchanged; fi/"
mutate missing-reports-drift     "s/^if \[ ! -e \"\$DST\" \]; then state=missing/if false; then state=missing/"
mutate check-always-exits-0      "s/^    \[ \"\$state\" = unchanged \]; exit \$?/    exit 0/"
mutate dry-run-installs          "s/^if \[ \"\$DRY\" -eq 1 \]; then echo \"would/if false; then echo \"would/"
mutate syntax-not-checked        "s/^sh -n \"\$SRC\" || /true || /"
mutate root-not-required         "s/^if \[ -z \"\${HONEY_REVIEW_DESK_INITD_DIR:-}\" \] \&\& \[ \"\$(id -u)\" -ne 0 \]; then/if false; then/"
mutate reinstall-not-noop        "s/^if \[ \"\$state\" = unchanged \]; then echo \"unchanged/if false; then echo \"unchanged/"
mutate diff-uncut                "s/diff -u \"\$DST\" \"\$SRC\" | head -40/diff -u \"\$DST\" \"\$SRC\"/"
mutate starts-the-service        "s/^echo \"installed \$DST\"/echo \"installed \$DST\"; rc-service honey-review-desk start/"
mutate places-a-second-file      "s/^echo \"installed \$DST\"/echo \"installed \$DST\"; cp \"\$SRC\" \"\$INITD\/other\"/"
mutate unknown-arg-accepted      "s/printf 'honey-review-desk-install: unknown argument: %s\\\\n' \"\$arg\" >\&2; exit 2/true/"
mutate missing-source-ok         "s/^\[ -r \"\$SRC\" \] || { echo \"missing \$SRC\" >\&2; exit 1; }/true/"
echo "mutants: $killed killed"
[ "$fail" = 0 ] || exit 1
exit 0
